export function validateReviewedZaCourseReconciliation(): string[] {
  const errors: string[] = [];
  const courseIds = new Set<string>();
  const placeIds = new Set<string>();
  const additionNames = new Set<string>();
  for (const item of [...REVIEWED_ZA_COURSE_UPDATES, ...REVIEWED_ZA_COURSE_ADDITIONS]) {
    if (!item.name.trim()) errors.push('course name is required');
    if (!item.placeId.trim()) errors.push('place id is required: ' + item.name);
    if (placeIds.has(item.placeId)) errors.push('duplicate place id: ' + item.placeId);
    placeIds.add(item.placeId);
    if (!Number.isFinite(item.lat) || item.lat < -35.5 || item.lat > -22) errors.push('invalid latitude: ' + item.name);
    if (!Number.isFinite(item.lon) || item.lon < 16 || item.lon > 33.5) errors.push('invalid longitude: ' + item.name);
    if (item.holes !== null && (!Number.isInteger(item.holes) || item.holes <= 0)) errors.push('invalid holes: ' + item.name);
  }
  for (const item of REVIEWED_ZA_COURSE_UPDATES) {
    if (!item.courseId) errors.push('update course id is required: ' + item.name);
    else if (courseIds.has(item.courseId)) errors.push('duplicate course id: ' + item.courseId);
    else courseIds.add(item.courseId);
  }
  for (const item of REVIEWED_ZA_COURSE_ADDITIONS) {
    if (additionNames.has(item.name)) errors.push('duplicate addition name: ' + item.name);
    additionNames.add(item.name);
  }
  return errors;
}

